def girth_at_least_7(edges, n):
    # Check no cycle of length 3,4,5,6 via BFS
    adj = [set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    # For each edge, BFS from u avoiding edge to check if v reachable in ≤ 5 steps
    for u,v in edges:
        # BFS from u in graph minus edge (u,v)
        dist = {u:0}
        frontier = [u]
        for d in range(1,6):
            new = []
            for x in frontier:
                for y in adj[x]:
                    if x==u and y==v: continue
                    if y==u and x==v: continue
                    if y not in dist:
                        dist[y]=d
                        new.append(y)
            frontier=new
        if v in dist and dist[v] <= 5:
            return False
    return True

