    # check adding edge (u,v) keeps girth ≥7. So in current graph (before add), no path from u to v with length ≤5.
    dist = {u:0}
    frontier=[u]
    for d in range(1,6):
        new=[]
        for x in frontier:
            for y in adj[x]:
                if y not in dist:
                    dist[y]=d; new.append(y)
        frontier=new
    return v not in dist or dist[v] > 5

